 m.update(document_kind='business-flow',manual_curated=True,title=title,review_status=status,participants=allpids,participant_ids=allpids,related_diagrams=[x['path'] for x in items],issue_ids=issue,limitations=notes,review_evidence={'date':'2026-11-09','scope':'Complete source-delimited narrative and literal diagram messages/directions checked; institutional examples retained separately.'})
 body='# '+title+'\n\n'+kb.source_link(root,p,src)+'; source heading P'+str(start)+', '+', '.join(x['source_locator'] for x in items)+'.\n\n## Purpose, trigger and common conditions\n\n'
